  hu: "Elutasítva, nem tervezett: ez a család olyan azonosítókat igényelne, amelyeket ez az átjáró nem vállal tárolni, ezért nem épül meg. A sor azért marad itt, hogy az elutasítás nyoma meglegyen.",
