      "zh-Hans": "一条 Webhook 进来自 Grafana 或 Alertmanager，手机上落下一张 security 卡。",
      "zh-Hant": "一條 Webhook 進來自 Grafana 或 Alertmanager，手機上落下一張 security 卡。",
