      th: "Webhook หนึ่งเส้นจาก Grafana หรือ Alertmanager เข้ามา แล้วการ์ด security หนึ่งใบบนมือถือก็เด้งขึ้น",
      fi: "Yksi webhook Grafanasta tai Alertmanagerista, yksi security-kortti puhelimeen.",
