      ko: "Grafana 또는 Alertmanager에서 들어오는 웹훅 하나, 휴대폰에 도착하는 보안 카드 하나입니다.",
      ar: "ويب هوك واحد وارد من Grafana أو Alertmanager، وبطاقة أمنية واحدة على الهاتف.",
