          ja: "POST /api/v1/plugins/caldav/freebusy は DTSTART、DTEND、DURATION、STATUS、TRANSP、RRULE だけを残し、SUMMARY、DESCRIPTION、LOCATION、ATTENDEE、ORGANIZER を捨て、繰り返し予定は件数を数えて飛ばし、空き枠を 可预约 と示します。",
