const ACCENT_BAR: Record<PluginModel["accent"], string> = {
  brand: "bg-brand-soft",
  mesh: "bg-mesh-soft",
  warn: "bg-warn",
};
/**
 * The two answers every card owes the visitor that are identical for all nine
 * modules, because the gateway really does not vary them. Authorisation is a
 * bearer token in `Authorization`: the root `POPOPX_ADMIN_TOKEN`, or a scoped
 * `pxa_…` token minted at `POST /api/v1/admin/tokens` with `core:<resource>:ro|rw`,
 * `plugin:<id>:ro|rw` or `*` scopes, stored only as a hash and shown once
 * (`gateway/app/api/admin.py`). Turning a service off is still the matching
 * `POPOPX_PLUGIN_*` boolean read at `gateway/app/config.py`. Written as one block
 * rather than nine, so the page cannot accidentally promise a per-connection
 * revocation the code does not have.
 */
const CREDENTIAL_NOTE: Localized<string> = {
  en: "Every call under /api/v1/plugins/* is authorised by a bearer token in the Authorization header. That is either the root POPOPX_ADMIN_TOKEN or a scoped pxa_ token minted at POST /api/v1/admin/tokens: its scopes are core:<resource>:ro|rw, plugin:<id>:ro|rw or *, it is stored only as a hash and the plaintext is returned once. What the module brings of its own is only the environment keys listed below.",
  ru: "Каждый вызов в /api/v1/plugins/* авторизует bearer-токен в заголовке Authorization. Это либо корневой POPOPX_ADMIN_TOKEN, либо скоупованный токен pxa_, выданный в POST /api/v1/admin/tokens: его области — core:<resource>:ro|rw, plugin:<id>:ro|rw или *, на диске хранится только хэш, а открытый текст возвращается один раз. Собственные секреты модуля — только перечисленные ниже переменные окружения.",
  de: "Jeden Aufruf unter /api/v1/plugins/* autorisiert ein Bearer-Token im Authorization-Header. Das ist entweder der Root-Token POPOPX_ADMIN_TOKEN oder ein gescoptes pxa_-Token aus POST /api/v1/admin/tokens: seine Scopes sind core:<resource>:ro|rw, plugin:<id>:ro|rw oder *, gespeichert wird nur ein Hash, der Klartext kommt einmal zurück. Was das Modul selbst mitbringt, sind nur die unten genannten Umgebungsschlüssel.",
  fr: "Chaque appel sous /api/v1/plugins/* est autorisé par un jeton bearer dans l’en-tête Authorization. C’est soit le jeton racine POPOPX_ADMIN_TOKEN, soit un jeton pxa_ à portée limitée émis par POST /api/v1/admin/tokens : ses portées sont core:<resource>:ro|rw, plugin:<id>:ro|rw ou *, seul un hachage est conservé et le texte clair n’est renvoyé qu’une fois. Les secrets propres au module se limitent aux variables d’environnement listées ci-dessous.",
  it: "Ogni chiamata sotto /api/v1/plugins/* è autorizzata da un token bearer nell’header Authorization. È il token radice POPOPX_ADMIN_TOKEN oppure un token pxa_ con scope emesso da POST /api/v1/admin/tokens: i suoi scope sono core:<resource>:ro|rw, plugin:<id>:ro|rw o *, su disco resta solo l’hash e il testo in chiaro viene restituito una volta. I segreti propri del modulo sono solo le variabili d’ambiente elencate qui sotto.",
  nl: "Elke aanroep onder /api/v1/plugins/* wordt geautoriseerd door een bearertoken in de Authorization-header. Dat is de root POPOPX_ADMIN_TOKEN of een scoped pxa_-token dat bij POST /api/v1/admin/tokens is aangemaakt: de scopes zijn core:<resource>:ro|rw, plugin:<id>:ro|rw of *, op schijf staat alleen een hash en de platte tekst komt één keer terug. Wat de module zelf meebrengt zijn alleen de hieronder genoemde omgevingsvariabelen.",
  cs: "Každý požadavek pod /api/v1/plugins/* autorizuje bearer token v hlavičce Authorization. Je to buď kořenový POPOPX_ADMIN_TOKEN, nebo token pxa_ s rozsahem vydaný v POST /api/v1/admin/tokens: jeho rozsahy jsou core:<resource>:ro|rw, plugin:<id>:ro|rw nebo *, na disku je jen hash a otevřený text se vrací jednou. Vlastní tajné údaje modulu jsou jen níže uvedené proměnné prostředí.",
  "zh-Hans": "/api/v1/plugins/* 下的每一次调用都由 Authorization 头里的 bearer token 授权，要么是根 POPOPX_ADMIN_TOKEN，要么是在 POST /api/v1/admin/tokens 签发的 pxa_ 作用域令牌：作用域为 core:<resource>:ro|rw、plugin:<id>:ro|rw 或 *，磁盘上只存哈希，明文只返回一次。模块自己带来的密钥只有下面列出的那几颗环境变量。",
  "zh-Hant": "/api/v1/plugins/* 下的每次呼叫都由 Authorization 標頭裡的 bearer token 授權，要麼是根 POPOPX_ADMIN_TOKEN，要麼是在 POST /api/v1/admin/tokens 簽發的 pxa_ 作用域權杖：作用域為 core:<resource>:ro|rw、plugin:<id>:ro|rw 或 *，磁碟上只存雜湊，明文只回傳一次。模組自帶的金鑰只有下面列出的那幾顆環境變數。",
  es: "Cada llamada bajo /api/v1/plugins/* la autoriza un token bearer en la cabecera Authorization. Es el POPOPX_ADMIN_TOKEN raíz o un token pxa_ con alcance emitido en POST /api/v1/admin/tokens: sus alcances son core:<resource>:ro|rw, plugin:<id>:ro|rw o *, en disco solo queda un hash y el texto claro se devuelve una vez. Lo que el módulo aporta por su parte son solo las variables de entorno listadas abajo.",
  pl: "Każde wywołanie pod /api/v1/plugins/* autoryzuje token bearer w nagłówku Authorization. To albo główny POPOPX_ADMIN_TOKEN, albo token pxa_ z zakresem wydany w POST /api/v1/admin/tokens: jego zakresy to core:<resource>:ro|rw, plugin:<id>:ro|rw lub *, na dysku zostaje tylko hash, a tekst jawny wraca raz. Własne sekrety modułu to tylko wymienione niżej zmienne środowiskowe.",
  ja: "/api/v1/plugins/* 配下の呼び出しはすべて Authorization ヘッダーの bearer トークンで認可されます。ルートの POPOPX_ADMIN_TOKEN か、POST /api/v1/admin/tokens で発行するスコープ付き pxa_ トークンで、スコープは core:<resource>:ro|rw、plugin:<id>:ro|rw、* のいずれかです。ディスクにはハッシュだけを保存し、平文は一度だけ返します。モジュール自身が持つ秘密情報は、下に並べた環境変数だけです。",
  th: "การเรียกใช้ใต้ /api/v1/plugins/* ทุกครั้งได้รับอนุญาตด้วย bearer token ใน header Authorization ซึ่งเป็นได้ทั้ง POPOPX_ADMIN_TOKEN ตัวหลัก หรือโทเคน pxa_ แบบกำหนด scope ที่ออกที่ POST /api/v1/admin/tokens โดย scope คือ core:<resource>:ro|rw, plugin:<id>:ro|rw หรือ * เก็บบนดิสก์เพียงแฮชและคืนข้อความธรรมดาเพียงครั้งเดียว ความลับของโมดูลเองมีแค่ตัวแปรสภาพแวดล้อมที่ระบุไว้ข้างล่าง",
  fi: "Jokaisen /api/v1/plugins/* -polun kutsun valtuuttaa Authorization-otsakkeen bearer-token. Se on joko juuri-POPOPX_ADMIN_TOKEN tai POST /api/v1/admin/tokens -osoitteessa myönnetty pxa_-token, jonka scopet ovat core:<resource>:ro|rw, plugin:<id>:ro|rw tai *, levylle jää vain hash ja selkokielinen arvo palautetaan kerran. Moduulin omat salaisuudet ovat vain alla luetellut ympäristömuuttujat.",
  uk: "Кожен виклик у /api/v1/plugins/* авторизує bearer-токен у заголовку Authorization. Це або кореневий POPOPX_ADMIN_TOKEN, або скоупований токен pxa_, виданий у POST /api/v1/admin/tokens: його області — core:<resource>:ro|rw, plugin:<id>:ro|rw чи *, на диску зберігається лише хеш, а відкритий текст повертається один раз. Власні секрети модуля — це лише перелічені нижче змінні середовища.",
  bg: "Всяко извикване под /api/v1/plugins/* се оторизира от bearer токен в заглавката Authorization. Това е или основният POPOPX_ADMIN_TOKEN, или токен pxa_ с обхват, издаден в POST /api/v1/admin/tokens: обхватите му са core:<resource>:ro|rw, plugin:<id>:ro|rw или *, на диска се пази само хеш, а откритият текст се връща веднъж. Собствените тайни на модула са само изброените по-долу променливи на средата.",
  tr: "/api/v1/plugins/* altındaki her çağrıyı Authorization başlığındaki bearer token yetkilendirir. Bu ya kök POPOPX_ADMIN_TOKEN ya da POST /api/v1/admin/tokens üzerinden üretilen kapsamlı bir pxa_ tokenıdır: kapsamları core:<resource>:ro|rw, plugin:<id>:ro|rw ya da * olur, diskte yalnızca hash tutulur ve açık metin bir kez döner. Modülün kendine ait sırları yalnızca aşağıda listelenen ortam değişkenleridir.",
  hu: "A /api/v1/plugins/* alatti minden hívást az Authorization fejlécben küldött bearer token jogosít. Ez vagy a gyökér POPOPX_ADMIN_TOKEN, vagy a POST /api/v1/admin/tokens végponton kiadott hatókörű pxa_ token: hatókörei core:<resource>:ro|rw, plugin:<id>:ro|rw vagy *, a lemezen csak hash marad, a nyílt szöveg pedig egyszer jön vissza. A modul saját titkai csak az alább felsorolt környezeti változók.",
  "pt-BR": "Toda chamada sob /api/v1/plugins/* é autorizada por um token bearer no header Authorization. Esse token é o POPOPX_ADMIN_TOKEN raiz ou um token pxa_ com escopo emitido em POST /api/v1/admin/tokens: seus escopos são core:<resource>:ro|rw, plugin:<id>:ro|rw ou *, ele é armazenado apenas como hash e o texto claro é retornado uma única vez. O que o módulo traz por conta própria são apenas as chaves de ambiente listadas abaixo.",
  ko: "/api/v1/plugins/* 아래의 모든 호출은 Authorization 헤더의 bearer 토큰으로 승인됩니다. 이는 루트 POPOPX_ADMIN_TOKEN이거나 POST /api/v1/admin/tokens에서 발급된 범위 지정 pxa_ 토큰입니다: 그 범위는 core:<resource>:ro|rw, plugin:<id>:ro|rw 또는 *이며, 해시로만 저장되고 평문은 한 번만 반환됩니다. 모듈이 자체적으로 제공하는 것은 아래에 나열된 환경 키뿐입니다.",
  ar: "كل استدعاء تحت /api/v1/plugins/* يُخوَّل برمز bearer في ترويسة Authorization. وهو إما POPOPX_ADMIN_TOKEN الجذري وإما رمز pxa_ محدود النطاق مُصدر عند POST /api/v1/admin/tokens: نطاقاته هي core:<resource>:ro|rw أو plugin:<id>:ro|rw أو *، ويُخزَّن كتجزئة فقط ويُعاد النص الواضح مرة واحدة. وما تجلبه الوحدة من عندها ليس إلا مفاتيح البيئة المسرودة أدناه.",
};

const REVOKE_NOTE: Localized<string> = {
  en: "Revocation is a switch, not a key list: set the module's POPOPX_PLUGIN_* boolean to 0 and restart the gateway; GET /api/v1/plugins then reports the module disabled and its routes stop answering. There is nothing to revoke per connection, because no per-connection credential is ever handed out.",
  ru: "Отзыв — это переключатель, а не список ключей: поставьте булев POPOPX_PLUGIN_* модуля в 0 и перезапустите шлюз; после этого GET /api/v1/plugins показывает модуль отключённым, а его маршруты перестают отвечать. Отзывать что-то отдельно для соединения нечего — учётных данных на соединение никто не выдаёт.",
  de: "Widerruf ist ein Schalter, keine Schlüsselliste: setze das POPOPX_PLUGIN_*-Boolean des Moduls auf 0 und starten das Gateway neu; danach meldet GET /api/v1/plugins das Modul als disabled und seine Routen antworten nicht mehr. Pro Verbindung gibt es nichts zu widerrufen, weil nie eine Berechtigung pro Verbindung ausgegeben wird.",
  fr: "La révocation est un interrupteur, pas une liste de clés : passez le booléen POPOPX_PLUGIN_* du module à 0 et redémarrez la passerelle ; ensuite GET /api/v1/plugins annonce le module désactivé et ses routes cessent de répondre. Rien n’est révocable connexion par connexion, aucun identifiant de connexion n’étant jamais distribué.",
  it: "La revoca è un interruttore, non un elenco di chiavi: imposta a 0 il booleano POPOPX_PLUGIN_* del modulo e riavvia il gateway; poi GET /api/v1/plugins segnala il modulo disattivato e le sue route non rispondono più. Non c’è nulla da revocare per singola connessione, perché nessuna credenziale per connessione viene distribuita.",
  nl: "Intrekken is een schakelaar, geen sleutellijst: zet de POPOPX_PLUGIN_*-boolean van de module op 0 en start de gateway opnieuw; daarna meldt GET /api/v1/plugins de module als uitgeschakeld en zijn routes stoppen met antwoorden. Er is per verbinding niets in te trekken, omdat er nooit een credential per verbinding wordt uitgegeven.",
  cs: "Zrušení je přepínač, ne seznam klíčů: dejte boolean POPOPX_PLUGIN_* modulu na 0 a restartujte gateway; pak GET /api/v1/plugins hlásí modul vypnutý a jeho routes přestanou odpovídat. Po jednotlivých spojení není co zrušit, protože žádné pověření na spojení se nikdy nevydává.",
  "zh-Hans": "撤销是一个开关，不是一份 key 清单：把该模块的 POPOPX_PLUGIN_* 布尔量置 0 并重启网关，GET /api/v1/plugins 就会把它报成 disabled，它的接口也不再应答。没有「按连接撤销」这回事，因为系统从来不会按连接下发凭证。",
  "zh-Hant": "撤銷是一個開關，不是一份 key 清單：把該模組的 POPOPX_PLUGIN_* 布林值設為 0 並重啟閘道，GET /api/v1/plugins 就會把它報成 disabled，它的介面也不再應答。沒有「按連線撤銷」這回事，因為系統從來不會按連線下發憑證。",
  es: "Revocar es un interruptor, no una lista de claves: pon el booleano POPOPX_PLUGIN_* del módulo en 0 y reinicia la pasarela; entonces GET /api/v1/plugins informa el módulo desactivado y sus rutas dejan de responder. No hay nada que revocar por conexión, porque nunca se entrega ninguna credencial por conexión.",
  pl: "Odwołanie to przełącznik, nie lista kluczy: ustaw wartość logiczną POPOPX_PLUGIN_* modułu na 0 i uruchom bramę ponownie; wtedy GET /api/v1/plugins zgłasza moduł jako wyłączony, a jego trasy przestają odpowiadać. Nie ma czego odwoływać dla poszczególnego połączenia, bo żadne poświadczenie na połączenie nigdy nie jest wydawane.",
  ja: "取り消しはスイッチであって、鍵のリストではありません。そのモジュールの POPOPX_PLUGIN_* ブール値を 0 にしてゲートウェイを再起動すれば、GET /api/v1/plugins は disabled を返し、そのルートは応答をやめます。接続単位の資格情報はそもそも配布されないため、接続単位で取り消すものは存在しません。",
  th: "การเพิกถอนคือสวิตช์ ไม่ใช่รายการคีย์: ตั้งค่า boolean POPOPX_PLUGIN_* ของโม듈เป็น 0 แล้วรีสตาร์ทเกตเวย์ จากนั้น GET /api/v1/plugins จะรายงานโม듈เป็น disabled และรูตของมันหยุดตอบ ไม่มีอะไรให้เพิกถอนทีละการเชื่อมต่อ เพราะไม่มีการจ่ายสิทธิ์ยืนยันเฉพาะการเชื่อมต่อตั้งแต่แรก",
  fi: "Peruutus on kytkin eikä avainlista: aseta moduulin POPOPX_PLUGIN_*-totuusarvo 0:aan ja käynnistä gateway uudelleen; sen jälkeen GET /api/v1/plugins ilmoittaa moduulin poistetuksi eikä sen reitit vastaa. Yksittäistä yhteyttä ei ole mitä peruuttaa, koska yhteyskohtaisia tunnuksia ei jaeta ollenkaan.",
  uk: "Відкликання — це перемикач, а не перелік ключів: поставте булеве значення POPOPX_PLUGIN_* модуля на 0 і перезапустіть шлюз; після цього GET /api/v1/plugins повідомляє, що модуль вимкнено, а його маршрути перестють відповідати. Відкликати щось окремо для з'єднання нічого, бо жодних облікових даних на з'єднання не видають.",
  bg: "Отменянето е превключвател, не списък с ключове: сложете булевата POPOPX_PLUGIN_* на модула на 0 и рестартирайте шлюза; след това GET /api/v1/plugins отчита модула като изключен и маршрутите му спират да отговарят. Няма какво да се отменя на ниво връзка, защото никога не се издават удостоверения за конкретна връзка.",
  tr: "İptal bir anahtardır, anahtar listesi değil: modülün POPOPX_PLUGIN_* boolean değerini 0 yapın ve ağ geçidini yeniden başlatın; ardından GET /api/v1/plugins modülü disabled olarak bildirir ve rotaları yanıt vermeyi bırakır. Bağlantı bazında iptal edilecek bir şey yok, çünkü bağlantı bazında hiçbir kimlik bilgisi dağıtılmıyor.",
  hu: "A visszavonás kapcsoló, nem kulcslista: állítsd a modul POPOPX_PLUGIN_* logikai értékét 0-ra, és indítsd újra az átkapcsolót; ezután a GET /api/v1/plugins letiltottként jelzi a modult, az útvonalai pedig nem válaszolnak többé. Kapcsolatonként nincs visszavonható dolog, mert kapcsolatonként sosem adunk ki hitelesítőt.",
  "pt-BR": "A revogação é um interruptor, não uma lista de chaves: defina o booleano POPOPX_PLUGIN_* do módulo como 0 e reinicie o gateway; o GET /api/v1/plugins então informa o módulo como desativado e as rotas dele param de responder. Não há nada a revogar por conexão, porque nenhuma credencial por conexão chega a ser entregue.",
  ko: "철회는 키 목록이 아니라 스위치입니다. 모듈의 POPOPX_PLUGIN_* 불리언을 0으로 설정하고 게이트웨이를 재시작하면, GET /api/v1/plugins가 해당 모듈을 비활성으로 보고하고 그 라우트가 응답을 멈춥니다. 연결별로 발급되는 자격 증명이 없으므로 연결 단위로 철회할 대상도 없습니다.",
  ar: "الإبطال مفتاح تشغيل لا قائمة مفاتيح: اضبط القيمة المنطقية POPOPX_PLUGIN_* للوحدة على 0 وأعد تشغيل البوابة؛ وعندها يبلّغ GET /api/v1/plugins بأن الوحدة معطّلة وتتوقف مساراتها عن الاستجابة. ولا يوجد ما يُبطَل لكل اتصال، لأن أي بيانات اعتماد لكل اتصال لا تُمنح أبدًا.",
};

function CardRow({
  label,
  children,
}: {
  readonly label: string;
  readonly children: ReactNode;
}): ReactElement {
  return (
    <div>
      <dt className="eyebrow">{label}</dt>
      <dd className="mt-1.5 text-[13px] leading-relaxed text-mute">{children}</dd>
    </div>
  );
}

function PluginPanel({ model, index }: { model: PluginModel; index: number }): ReactElement {
  const { locale } = useLocale();
  const name = useCopy(model.name);
  const hook = useCopy(model.hook);
  const capability = useCopy(Q_CAPABILITY);
  const credential = useCopy(Q_CREDENTIAL);
  const dataflow = useCopy(Q_DATAFLOW);
  const revocation = useCopy(Q_REVOKE);
  const credentialNote = useCopy(CREDENTIAL_NOTE);
  const revocationNote = useCopy(REVOKE_NOTE);
  const shipLabel = useCopy(STATE_LABEL);
  const shipWord = useCopy(SHIP_WORD[model.status]);
  const categoryLabel = useCopy(CATEGORY_COPY[model.category]);
  const keysLabel = useCopy(KEYS_LABEL);
  const routeLabel = useCopy(ROUTE_LABEL);
  const fileLabel = useCopy(FILE_LABEL);
  const on = model.status === "default-on";
  const number = String(index + 1).padStart(2, "0");

  return (
    <article className="glass glass-hover relative flex flex-col overflow-hidden p-5 sm:p-6 [overflow-wrap:anywhere]">
      <span
        aria-hidden
        className={`absolute inset-x-0 top-0 h-px ${ACCENT_BAR[model.accent]} opacity-60`}
      />
      <header className="flex flex-wrap items-start gap-3">
        {/* A full-width basis below sm: the pill is a long word in German or Italian, and with
            flex-1's 0% basis the title column was left holding the 7px that the pill did not take. */}
        <div className="min-w-0 flex-1 basis-full sm:basis-0">
          <p className="font-mono text-[11px] tracking-[0.18em] text-faint"><bdi dir="ltr">
            {number} / {model.code}
            </bdi></p>
          <h3 className="mt-1.5 text-[17px] font-semibold leading-snug text-white">{name}</h3>
        </div>
        <span className="pill min-w-0 sm:shrink-0 sm:whitespace-nowrap">
          <StatusDot tone={on ? "brand" : "warn"} pulse={on} />
          <span className="text-[11px]">
            {shipLabel} · {shipWord}
          </span>
        </span>
      </header>

      <p className="mt-2 text-[11.5px] font-medium tracking-[0.14em] text-brand-soft uppercase">
        {categoryLabel}
      </p>

      <dl className="mt-5 space-y-4">
        <CardRow label={capability}>{hook}</CardRow>
        <CardRow label={credential}>
          {credentialNote}
          <span className="eyebrow mt-3 block">{keysLabel}</span>
          <span className="mt-2 flex flex-wrap gap-1.5">
            {model.keys.map((key) => (
              <code key={key} className="chip font-mono text-[10.5px] text-brand-soft">
                {key}
              </code>
            ))}
          </span>
        </CardRow>
        <CardRow label={dataflow}>
          <span className="block space-y-2">
            {model.facts.map((fact) => (
              <span key={pick(fact.k, locale)} className="block">
                <span className="font-mono text-[11px] text-faint">{pick(fact.k, locale)}</span>
                <span className="mt-0.5 block">{pick(fact.v, locale)}</span>
              </span>
            ))}
          </span>
        </CardRow>
        <CardRow label={revocation}>{revocationNote}</CardRow>
      </dl>

      <div className="hairline-top mt-auto pt-4 text-[11px] text-faint">
        <div className="flex flex-wrap items-center gap-x-3 gap-y-1.5">
          <span>
            {routeLabel}
            <code className="ms-1.5 font-mono text-mesh-soft">{model.route}</code>
          </span>
          <span aria-hidden>|</span>
          <span>
            {fileLabel}
            <code className="ms-1.5 font-mono">{model.file}</code>
          </span>
        </div>
      </div>
    </article>
  );
}

function StepCard({
  number,
  title,
  copy,
}: {
  readonly number: string;
  readonly title: string;
  readonly copy: string;
}): ReactElement {
  return (
    <li className="glass-inset relative p-4">
      <p className="font-mono text-[11px] tracking-[0.18em] text-brand-soft"><bdi dir="ltr">{number}</bdi></p>
      <h4 className="mt-1.5 text-[13.5px] font-semibold leading-snug text-white">{title}</h4>
      <p className="mt-2 text-[12.5px] leading-relaxed text-mute">{copy}</p>
    </li>
  );
}

export function PluginsShowcase(): ReactElement {
  const { locale } = useLocale();
  const [filter, setFilter] = useState<FilterValue>(CATEGORY_ALL);
  const legendSource = useCopy(LEGEND_SOURCE);
  const legendMeter = useCopy(LEGEND_METER);
  const legendDisabled = useCopy(LEGEND_DISABLED);
  const filterLabel = useCopy(FILTER_LABEL);
  const filterAria = useCopy(FILTER_ARIA);
  const roadmapLabel = useCopy(ROADMAP_LABEL);
  const roadmapTitle = useCopy(ROADMAP_TITLE);
  const roadmapSub = useCopy(ROADMAP_SUB);
  const roadmapNeeds = useCopy(ROADMAP_NEEDS);
  const roadmapNoDate = useCopy(ROADMAP_NO_DATE);
  const roadmapShipped = useCopy(ROADMAP_SHIPPED_NOTE);
  const roadmapDeclinedLabel = useCopy(ROADMAP_DECLINED_LABEL);
  const roadmapDeclinedNote = useCopy(ROADMAP_DECLINED_NOTE);
  const stepsTitle = useCopy(STEPS_TITLE);
  const step1Title = useCopy(STEP_1_TITLE);
  const step1Copy = useCopy(STEP_1_COPY);
  const step2Title = useCopy(STEP_2_TITLE);
  const step2Copy = useCopy(STEP_2_COPY);
  const step3Title = useCopy(STEP_3_TITLE);
  const step3Copy = useCopy(STEP_3_COPY);
  const step4Title = useCopy(STEP_4_TITLE);
  const step4Copy = useCopy(STEP_4_COPY);
  const census = useCopy(CENSUS_TEXT);
  const footerTitle = useCopy(FOOTER_TITLE);
  const footerBody = useCopy(FOOTER_BODY);
  const sampleCaption = useCopy(FOOTER_SAMPLE_CAPTION);

  const visible = PLUGINS.filter(
    (model) => filter === CATEGORY_ALL || model.category === filter,
  );

  return (
    <section id="plugins" className="relative py-16 sm:py-20">
      <div aria-hidden className="pointer-events-none absolute inset-0 grain opacity-[0.06]" />
      <div className="section-wrap relative">
        <SectionHeading eyebrow={EYEBROW} title={TITLE} subtitle={SUBTITLE} />

        <div className="mt-6 flex flex-wrap gap-2">
          <span className="pill">{legendSource}</span>
          <span className="pill">{legendMeter}</span>
          <span className="pill">
            <StatusDot tone="warn" />
            {legendDisabled}
          </span>
        </div>

        <div className="glass mt-8 p-5 sm:p-6">
          <h3 className="text-[15px] font-semibold text-white">{stepsTitle}</h3>
          <ol className="mt-4 grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">
            <StepCard number="01" title={step1Title} copy={step1Copy} />
            <StepCard number="02" title={step2Title} copy={step2Copy} />
            <StepCard number="03" title={step3Title} copy={step3Copy} />
            <StepCard number="04" title={step4Title} copy={step4Copy} />
          </ol>
        </div>

        <div
          role="group"
          aria-label={filterAria}
          className="mt-8 flex flex-wrap items-center gap-2"
        >
          <span className="eyebrow me-1">{filterLabel}</span>
          {FILTER_CHIPS.map((chip) => {
            const active = chip.value === filter;
            return (
              <button
                key={chip.value}
                type="button"
                onClick={() => setFilter(chip.value)}
                aria-pressed={active}
                className={`pill transition ${
                  active ? "!border-brand-soft/60 !bg-brand/20 text-white" : "text-mute"
                } ${FOCUS}`}
              >
                {pick(chip.copy, locale)}
              </button>
            );
          })}
        </div>

        <div className="mt-5 grid grid-cols-1 gap-4 md:grid-cols-2">
          {visible.map((model, index) => (
            <PluginPanel key={model.code} model={model} index={index} />
          ))}
        </div>

        <div className="glass mt-6 p-5 sm:p-6">
          <div className="flex flex-wrap items-center gap-3">
            <span className="pill">
              <StatusDot tone="alert" />
              {roadmapLabel}
            </span>
            <h3 className="text-[15px] font-semibold text-white">{roadmapTitle}</h3>
          </div>
          <p className="mt-2.5 text-[13px] leading-relaxed text-mute">{roadmapSub}</p>
          <ul className="mt-5 space-y-4">
            {ROADMAP.map((item) => {
              const declined = item.state === "declined";
              return (
                <li key={item.brand} className="glass-inset p-4">
                  <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
                    <span className="pill whitespace-nowrap">
                      <StatusDot tone={declined ? "alert" : "warn"} />
                      {declined ? roadmapDeclinedLabel : roadmapLabel}
                    </span>
                    <code className="font-mono text-[11.5px] text-warn">{item.brand}</code>
                    <span className="text-[13.5px] font-medium text-white">
                      {pick(item.label, locale)}
                    </span>
                  </div>
                  <p className="eyebrow mt-3">{roadmapNeeds}</p>
                  <p className="mt-1.5 min-w-0 text-[12.5px] leading-relaxed text-mute [overflow-wrap:anywhere]">
                    {pick(item.caption, locale)}
                  </p>
                  {declined ? (
                    <p className="mt-1.5 min-w-0 text-[12px] leading-relaxed text-faint [overflow-wrap:anywhere]">
                      {roadmapDeclinedNote}
                    </p>
                  ) : null}
                </li>
              );
            })}
          </ul>
          <p className="mt-5 text-[12.5px] leading-relaxed text-faint">{roadmapNoDate}</p>
          <p className="mt-2.5 text-[12.5px] leading-relaxed text-faint">{roadmapShipped}</p>
        </div>

        <div className="glass mt-4 grid grid-cols-1 gap-5 p-5 sm:p-6 lg:grid-cols-2">
          <div>
            <h3 className="text-[15px] font-semibold text-white">{footerTitle}</h3>
            <p className="mt-2.5 text-[13px] leading-relaxed text-mute">{footerBody}</p>
            <p className="mt-3 font-mono text-[11px] leading-relaxed text-faint">{census}</p>
          </div>
          <CodeBlock code={PLUGIN_STATUS_SAMPLE} caption={sampleCaption} maxHeightClass="max-h-56" />
        </div>
      </div>
    </section>
  );
}
